import { DictionaryEntry } from './enMmDictionary';

// Compact helper to generate clean DictionaryEntry items for essential vocabulary
function w(
  id: string,
  en: string,
  pos: string,
  mm: string,
  enDef: string,
  exampleEn: string,
  exampleMm: string,
  phonetic?: string,
  synonyms?: string[],
  antonyms?: string[]
): DictionaryEntry {
  return {
    id: `core-${id}`,
    en,
    phonetic,
    pos,
    mm,
    enDef,
    exampleEn,
    exampleMm,
    synonyms,
    antonyms,
    category: 'general',
  };
}

